package io.github.templeosmobile.core

import io.github.templeosmobile.core.holyc.*
import io.github.templeosmobile.core.kernel.*
import io.github.templeosmobile.core.ui.Json
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/**
 * Runs the shared, source-derived program scenarios (shared/fidelity/scenarios.json, generated by
 * tools/fidelity/extract_scenarios.py from docs/fidelity-audit/data/specs): each original catalog
 * program is booted from the bundled drive in virtual time, gets the scenario's input, and one
 * global (or "exited") is compared with the value the original source implies. The Swift runner
 * (ScenarioTests) executes the same file.
 *
 *   default                     the REGRESSION list (fast, covers the audit's fixes)
 *   -Dtempleos.scenarios=all    every scenario that is not slow (results: build/scenario-results.json)
 *   -Dtempleos.scenarios=slow   also the slow ones;  =<prefix>[,<prefix>] by id prefix
 */
class ScenarioTest {
    companion object {
        /** Fast scenarios that check the audit's fixes on the original programs. */
        val REGRESSION = listOf(
            "game.battlelines#0", "game.battlelines#1", "game.digits#0", "game.digits#2", "game.circletrace#2",
            "game.flapbat#0", "game.flapbat#1", "game.zing#0", "game.zing#1", "game.raindrops#2", "demo.mousedemo#1",
            "demo.mousedemo#2", "demo.charanimation#1", "game.elephantwalk#1", "game.elephantwalk#0", "game.rocket#1",
            "game.whap#0", "game.whap#1", "demo.speedline#2",
            "demo.cartesian#3", "demo.scrollbars#3", "demo.transform#4", "demo.elephant#1", "app.span#1", "demo.collision#1", "game.tictactoe#0", "game.tictactoe#1",
        )

        fun keyOf(k: String): Pair<Int, Long> = when (k) {
            "CH_ESC", "ESC" -> Keys.special(Keys.SC_ESC)
            "CH_SHIFT_ESC" -> Keys.special(Keys.SC_ESC, shift = true)
            "SC_ESC" -> Keys.special(Keys.SC_ESC)
            "SC_ENTER" -> Keys.special(Keys.SC_ENTER)
            "SC_SPACE" -> Keys.forChar(' '.code)
            "SC_CURSOR_UP" -> Keys.special(Keys.SC_CURSOR_UP)
            "SC_CURSOR_DOWN" -> Keys.special(Keys.SC_CURSOR_DOWN)
            "SC_CURSOR_LEFT" -> Keys.special(Keys.SC_CURSOR_LEFT)
            "SC_CURSOR_RIGHT" -> Keys.special(Keys.SC_CURSOR_RIGHT)
            "SC_HOME" -> Keys.special(Keys.SC_HOME)
            "SC_END" -> Keys.special(Keys.SC_END)
            "SC_PAGE_UP" -> Keys.special(Keys.SC_PAGE_UP)
            "SC_PAGE_DOWN" -> Keys.special(Keys.SC_PAGE_DOWN)
            "SC_DELETE" -> Keys.special(Keys.SC_DELETE)
            "SC_BACKSPACE" -> Keys.special(Keys.SC_BACKSPACE)
            "SC_TAB" -> Keys.special(Keys.SC_TAB)
            else -> if (k.length == 1) Keys.forChar(k[0].code and 0xFF)
                else if (k.startsWith("SC_F") && k.substring(4).toIntOrNull() != null) {
                    val n = k.substring(4).toInt(); Keys.special(if (n <= 10) Keys.SC_F1 + n - 1 else 0x57 + n - 11)
                } else error("unknown key $k")
        }
    }

    class Result(val id: String, val status: String, val detail: String)

    private class ScenarioEnv(fs: VirtualFs, private val answers: ArrayDeque<Long>, private val memMb: Int) : KernelEnv {
        override val fs: VirtualFs = fs
        override fun runtimeFile(name: String): ByteArray? = File(SHARED, "runtime/$name").takeIf { it.exists() }?.readBytes()
        override fun entropy(): Long = 12345
        override val memoryLimit: Int get() = memMb shl 20
        override fun popupRequested(kernel: Kernel, req: PopupRequest) {
            req.result = answers.removeFirstOrNull() ?: req.items.firstOrNull { it.value != -1L }?.value ?: -1
        }
    }

    private fun findMember(c: ClassType, n: String): Member? = c.find(n) ?: c.base?.let { findMember(it, n) }

    /** Reads a probe path (`a.b[2]->c`, `$main.x`) with the compiler's own types. */
    private fun probe(k: Kernel, path: String): Double {
        val toks = Regex("""\$?[A-Za-z_\u0080-\u00FF][A-Za-z0-9_\u0080-\u00FF]*|->|\.|\[|]|\d+""").findAll(path).map { it.value }.toList()
        var i = 0
        var addr: Long; var type: Type
        val first = toks[i++]
        if (first == "\$main") { addr = k.mainTask!!.fsAddr.toLong(); type = k.prog.classes["CTask"]!! }
        else { val g = k.prog.globals[first] as? GlobalSym ?: error("no global $first"); addr = g.addr.toLong(); type = g.type }
        while (i < toks.size) {
            when (toks[i++]) {
                ".", "->" -> {
                    var t = type
                    if (t is PtrType) { addr = k.mem.ld8(k.mem.check(addr, 8)); t = t.target }
                    val c = t as? ClassType ?: error("$path: not a class at ${toks[i]}")
                    val m = findMember(c, toks[i++]) ?: error("$path: no member ${toks[i - 1]}")
                    addr += m.offset; type = m.type
                }
                "[" -> {
                    val n = toks[i++].toLong(); i++ // ]
                    when (val t = type) {
                        is ArrType -> { addr += n * t.elem.size; type = t.elem }
                        is PtrType -> { addr = k.mem.ld8(k.mem.check(addr, 8)) + n * t.target.size; type = t.target }
                        else -> error("$path: not indexable")
                    }
                }
            }
        }
        val t = type
        val a = k.mem.check(addr, maxOf(1, t.size))
        return when {
            t is F64Type -> java.lang.Double.longBitsToDouble(k.mem.ld8(a))
            t is IntType -> {
                val v = when (t.size) { 1 -> k.mem.ld1(a); 2 -> k.mem.ld2(a); 4 -> k.mem.ld4(a); else -> k.mem.ld8(a) }
                if (t.signed) when (t.size) { 1 -> v.toByte().toLong(); 2 -> v.toShort().toLong(); 4 -> v.toInt().toLong(); else -> v }.toDouble()
                else if (t.size == 8) java.lang.Long.toUnsignedString(v).toDouble() else v.toDouble()
            }
            t is ClassType && t.valueType != null -> k.mem.ld8(a).toDouble()
            t is PtrType -> k.mem.ld8(a).toDouble()
            else -> error("$path is not a scalar ($t)")
        }
    }

    private fun runOne(sc: Map<String, Any?>, bundle: () -> VirtualFs): Result {
        val id = sc["id"] as String
        @Suppress("UNCHECKED_CAST") val steps = sc["steps"] as List<List<Any?>>
        @Suppress("UNCHECKED_CAST") val expect = sc["expect"] as Map<String, Any?>
        val answers = ArrayDeque<Long>()
        for (s in steps) if (s[0] == "popup") answers.add((s[1] as Number).toLong())
        val prog = sc["program"] as String
        val k = Kernel(ScenarioEnv(bundle(), answers, if (prog.contains("Talons")) 96 else 32), prog.substringAfterLast('/'))
        k.virtualTime = true
        k.boot()
        val fs = k.env.fs!!
        k.runProgram(prog, fs.readFile(prog) ?: return Result(id, "ERROR", "no file"))
        val wallEnd = System.nanoTime() + 120_000_000_000L
        fun advance(ms: Long) {
            val stop = k.now() + ms * 1_000_000
            k.virtualStopAt = stop
            while (k.now() < stop && !k.finished && System.nanoTime() < wallEnd) if (k.step(50_000_000) < 0) break
        }
        fun mouse(x: Int, y: Int, l: Boolean, r: Boolean) = k.post(KInput.Mouse(x, y, l, r))
        advance(1)
        for (s in steps) {
            when (s[0]) {
                "wait_ms" -> advance((s[1] as Number).toLong())
                "key" -> { val (ch, c) = keyOf(s[1] as String); k.post(KInput.Key(ch, c, true)); k.post(KInput.Key(ch, c or Keys.SCF_KEY_UP, false)); advance(40) }
                "key_down" -> { val (ch, c) = keyOf(s[1] as String); k.post(KInput.Key(ch, c, true)); advance(1) }
                "key_up" -> { val (ch, c) = keyOf(s[1] as String); k.post(KInput.Key(ch, c or Keys.SCF_KEY_UP, false)); advance(1) }
                "click", "rclick" -> {
                    val x = (s[1] as Number).toInt(); val y = (s[2] as Number).toInt(); val r = s[0] == "rclick"
                    mouse(x, y, !r, r); advance(70); mouse(x, y, false, false); advance(70)
                }
                "drag" -> {
                    val x0 = (s[1] as Number).toInt(); val y0 = (s[2] as Number).toInt(); val x1 = (s[3] as Number).toInt(); val y1 = (s[4] as Number).toInt()
                    mouse(x0, y0, true, false); advance(50)
                    for (j in 1..5) { mouse(x0 + (x1 - x0) * j / 5, y0 + (y1 - y0) * j / 5, true, false); advance(40) }
                    mouse(x1, y1, false, false); advance(50)
                }
                "popup" -> advance(1) // answered in order by ScenarioEnv
                "menu" -> {
                    val path = s[1] as String
                    var m: MenuSnap? = null
                    for (j in 0 until 40) { m = k.menuSnapshot.firstOrNull { it.path == path }; if (m != null) break; advance(50) }
                    if (m == null) return Result(id, "ERROR", "menu $path not found").also { k.terminate("done") }
                    k.post(KInput.Raw(m.msgCode.toInt(), m.a1, m.a2)); advance(40)
                }
            }
        }
        val res = try {
            if (expect.containsKey("exited")) {
                val want = expect["exited"] as Boolean
                if (k.finished == want) Result(id, "PASS", "exited=${k.finished}") else Result(id, "FAIL", "exited=${k.finished} (want $want) ${k.exitMessage ?: ""}")
            } else {
                val v = probe(k, expect["global"] as String)
                val want = (expect["value"] as Number).toDouble()
                val ok = when (expect["op"]) { "<" -> v < want; "<=" -> v <= want; "==" -> v == want; "!=" -> v != want; ">=" -> v >= want; else -> v > want }
                Result(id, if (ok) "PASS" else "FAIL", "${expect["global"]}=$v ${expect["op"]} $want" + (if (k.finished) " (ended: ${k.exitMessage ?: "normally"})" else ""))
            }
        } catch (e: Exception) { Result(id, "ERROR", e.toString().take(200)) }
        k.terminate("done")
        return res
    }

    @Test fun scenarios() {
        val sel = System.getProperty("templeos.scenarios") ?: "regression"
        @Suppress("UNCHECKED_CAST")
        val all = (Json.parse(File(SHARED, "fidelity/scenarios.json").readText()) as Map<String, Any?>)["scenarios"] as List<Map<String, Any?>>
        val chosen = all.filter { sc ->
            val id = sc["id"] as String
            when (sel) {
                "regression" -> id in REGRESSION
                "all" -> sc["slow"] != true
                "slow" -> true
                else -> sel.split(",").any { id.startsWith(it) }
            }
        }
        val root = File(SHARED, "bundled-fs")
        val bundle = { LayeredFs(DirBundle(root, File(SHARED, "bundled-fs.index")), java.nio.file.Files.createTempDirectory("scen").toFile()) }
        val results = chosen.map { sc ->
            val r = try { runOne(sc, bundle) } catch (e: Throwable) { Result(sc["id"] as String, "ERROR", e.toString().take(200)) }
            println("SCENARIO ${r.id} ${r.status} ${r.detail}")
            r
        }
        File("build").mkdirs()
        File("build/scenario-results.json").writeText(results.joinToString(",\n", "[\n", "\n]\n") {
            "{\"id\":\"${it.id}\",\"status\":\"${it.status}\",\"detail\":\"${it.detail.replace("\\", "\\\\").replace("\"", "'").replace(Regex("[\\u0000-\\u001f]"), " ")}\"}"
        })
        if (sel == "regression") {
            val bad = results.filter { it.status != "PASS" }
            assertTrue("scenarios failed:\n" + bad.joinToString("\n") { "${it.id} ${it.status} ${it.detail}" }, bad.isEmpty())
            assertEquals("every regression scenario exists", REGRESSION.size, results.size)
        }
    }
}
